<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/auth.php';

function get_dashboard_data(int $user_id): array {
    $db = db();

    $user = get_user($user_id);
    if (!$user) return [
        'virtual_accounts' => [],
        'transactions' => [],
        'notif_count' => 0
    ];

    // Virtual accounts
    $va = $db->prepare("SELECT * FROM virtual_accounts WHERE user_id = ? AND is_active = 1 ORDER BY provider");
    $va->execute([$user_id]);
    $virtual_accounts = $va->fetchAll();

    // Recent transactions (last 3)
    $tx = $db->prepare(
        "SELECT * FROM transactions WHERE user_id = ? ORDER BY created_at DESC LIMIT 3"
    );
    $tx->execute([$user_id]);
    $transactions = $tx->fetchAll();

    // Unread notifications count
    $nc = $db->prepare(
        "SELECT COUNT(*) FROM notifications WHERE (user_id = ? OR user_id IS NULL) AND is_read = 0"
    );
    $nc->execute([$user_id]);
    $notif_count = (int)$nc->fetchColumn();

    // Monthly spending
    $ms = $db->prepare(
        "SELECT COALESCE(SUM(amount),0) FROM transactions 
         WHERE user_id=? AND type='debit' AND status='success' 
         AND MONTH(created_at)=MONTH(NOW()) AND YEAR(created_at)=YEAR(NOW())"
    );
    $ms->execute([$user_id]);
    $monthly_spend = (float)$ms->fetchColumn();

    // Virtual card USD balance (sum of active cards)
    $vc = $db->prepare("SELECT COALESCE(SUM(balance),0) FROM virtual_cards WHERE user_id=? AND status='active'");
    $vc->execute([$user_id]);
    $usd_balance = (float)$vc->fetchColumn();

    return compact('user','virtual_accounts','transactions','notif_count','monthly_spend','usd_balance');
}

function get_user_transactions(int $user_id, int $page=1, int $per_page=20, string $filter='', string $start_date='', string $end_date='', string $search=''): array {
    $db = db();
    $offset = ($page - 1) * $per_page;
    $where = "WHERE user_id = ?";
    $params = [$user_id];

    if ($filter && in_array($filter, ['airtime','data','electricity','cabletv','airtime_to_cash','exam_pin','recharge_card','data_card','bank_transfer','wallet_funding','wallet_transfer','cashback','bulk_sms'])) {
        $where .= " AND category = ?";
        $params[] = $filter;
    }
    
    if ($start_date && preg_match('/^\d{4}-\d{2}-\d{2}$/', $start_date)) {
        $where .= " AND DATE(created_at) >= ?";
        $params[] = $start_date;
    }
    
        if ($end_date && preg_match('/^\d{4}-\d{2}-\d{2}$/', $end_date)) {
        $where .= " AND DATE(created_at) <= ?";
        $params[] = $end_date;
    }
    
    if ($search) {
        $where .= " AND (description LIKE ? OR transaction_ref LIKE ? OR meta LIKE ?)";
        $params[] = "%$search%";
        $params[] = "%$search%";
        $params[] = "%$search%";
    }

    $count_stmt = $db->prepare("SELECT COUNT(*) FROM transactions $where");
    $count_stmt->execute($params);
    $total = (int)$count_stmt->fetchColumn();

    $params[] = $per_page;
    $params[] = $offset;
    $stmt = $db->prepare("SELECT * FROM transactions $where ORDER BY created_at DESC LIMIT ? OFFSET ?");
    $stmt->execute($params);
    $rows = $stmt->fetchAll();

    return [
        'data'       => $rows,
        'total'      => $total,
        'page'       => $page,
        'per_page'   => $per_page,
        'total_pages'=> (int)ceil($total / $per_page),
    ];
}

function get_tx_logo_html(string $description, string $default_html): string {
    $map = [
        'betting' => 'data:image/jpeg;base64,',
        'mtn' => 'data:image/jpeg;base64,',
        'glo' => 'data:image/jpeg;base64,',
        'airtel' => 'data:image/png;base64,',
        '9mobile' => 'data:image/png;base64,',
        'dstv' => 'data:image/png;base64,',
        'gotv' => 'data:image/png;base64,',
        'startimes' => 'data:image/jpg;base64,',
        'showmax' => 'data:image/jpeg;base64,',
        'smile' => 'data:image/jpeg;base64,',
        'spectranet' => 'data:image/jpeg;base64,',
        'ikeja' => 'data:image/png;base64,',
        'eko' => 'data:image/jpg;base64,',
        'abuja' => 'data:image/jpg;base64,',
        'kano' => 'data:image/png;base64,',
        'enugu' => 'data:image/png;base64,',
        'port harcourt' => 'data:image/jpg;base64,',
        'ibadan' => 'data:image/jpg;base64,',
        'kaduna' => 'data:image/jpg;base64,',
        'jos' => 'data:image/jpg;base64,',
        'benin' => 'data:image/jpg;base64,',
        'yola' => 'data:image/jpg;base64,',
        'waec' => 'data:image/png;base64,',
        'neco' => 'data:image/png;base64,',
        'nabteb' => 'data:image/png;base64,'
    ];
    $desc_lower = strtolower($description);
    foreach($map as $key => $file) {
        if (strpos($desc_lower, $key) !== false) {
            return '<img src="' . $file . '" alt="" class="w-full h-full object-cover" style="border-radius: inherit;">';
        }
    }
    return $default_html;
}

?>
